2	import * as THREE from "three";
3	import { GLTFLoader } from "three/addons/loaders/GLTFLoader.js";
4	import { DRACOLoader } from "three/addons/loaders/DRACOLoader.js";
5	import { HDRLoader } from "three/addons/loaders/HDRLoader.js";
6	import type {
7	  LoadGLTFOptions,
8	  LoadGLTFResult,
9	  GLTFLoaderPluginRegister,
10	} from "../types/runtime.types.js";
11	import { disposeObject3D } from "../utils/disposeObject3D.js";
12	export { type LoadGLTFOptions, type LoadGLTFResult } from "../types/runtime.types.js";
13	
14	function registerPBRSpecularGlossinessPlugin(loader: GLTFLoader): void {
15	  const registrableLoader = loader as GLTFLoader & GLTFLoaderPluginRegister;
16	  if (typeof registrableLoader.register !== "function") return;
17	  registrableLoader.register(() => ({
18	    name: "KHR_materials_pbrSpecularGlossiness",
19	  }));
20	}
