163	  private _createMixersFromClips(
164	    clips: THREE.AnimationClip[],
165	    model: THREE.Object3D,
166	  ): THREE.AnimationMixer[] {
167	    if (clips.length === 0) return [];
168	    const mixer = new THREE.AnimationMixer(model);
169	    clips.forEach((clip) => mixer.clipAction(clip).play());
170	    return [mixer];
171	  }
